\set ON_ERROR_STOP on
BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE SCHEMA hg_lib03;
CREATE TABLE hg_lib03.sources (id text NOT NULL, version text NOT NULL, metadata_sha256 text NOT NULL, raw_json jsonb NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE hg_lib03.parts (id text NOT NULL, version text NOT NULL, PRIMARY KEY(id,version), FOREIGN KEY(id,version) REFERENCES hg_lib03.sources(id,version));
CREATE TABLE hg_lib03.reference_designs (id text NOT NULL, version text NOT NULL, PRIMARY KEY(id,version), FOREIGN KEY(id,version) REFERENCES hg_lib03.sources(id,version));
CREATE TABLE hg_lib03.modules (id text NOT NULL, version text NOT NULL, PRIMARY KEY(id,version), FOREIGN KEY(id,version) REFERENCES hg_lib03.sources(id,version));
CREATE TABLE hg_lib03.projects (id text NOT NULL, version text NOT NULL, PRIMARY KEY(id,version), FOREIGN KEY(id,version) REFERENCES hg_lib03.sources(id,version));
CREATE TABLE hg_lib03.validation_runs (id text NOT NULL, version text NOT NULL, PRIMARY KEY(id,version), FOREIGN KEY(id,version) REFERENCES hg_lib03.sources(id,version));
CREATE TABLE hg_lib03.entity_links (from_id text NOT NULL, from_version text NOT NULL, to_id text NOT NULL, to_version text NOT NULL, relation text NOT NULL, PRIMARY KEY(from_id,from_version,to_id,to_version,relation), FOREIGN KEY(from_id,from_version) REFERENCES hg_lib03.sources(id,version), FOREIGN KEY(to_id,to_version) REFERENCES hg_lib03.sources(id,version));
COMMIT;
